    "bio": "張濟之侄，割據宛城被稱為「北地槍王」。賈詡為其軍師。曹操南征宛城張繡迎降，曹操納其嬸母鄒氏，張繡受辱大怒發動宛城夜襲，大破曹操斬其長子曹昂、侄曹安民及猛將典韋。官渡前夕聽從賈詡勸告再度降曹，曹操既往不咎結為兒女親家。從征烏桓途中病逝。",
